#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    const long price[5] = {10, 20, 30, 40, 50}; // assumed prices per SKU
    long stock[5] = {0, 0, 0, 0, 0};
    long revenue = 0;
    int i = 1; // start after program name
    while (i + 2 < argc) {
        char *op_str = argv[i];
        long sku = strtol(argv[i + 1], NULL, 10);
        long qty = strtol(argv[i + 2], NULL, 10);
        i += 3;
        if (op_str[0] == 'R' && op_str[1] == '\0') { // RESTOCK
            if (sku < 0 || sku >= 5) {
                puts("INVALID_SKU");
                continue;
            }
            if (qty < 0) {
                puts("INVALID_OP");
                continue;
            }
            stock[sku] += qty;
            printf("RESTOCK sku=%ld qty=%ld\n", sku, qty);
        } else if (op_str[0] == 'S' && op_str[1] == '\0') { // SELL
            if (sku < 0 || sku >= 5) {
                puts("INVALID_SKU");
                continue;
            }
            if (qty < 0) {
                puts("INVALID_OP");
                continue;
            }
            if (stock[sku] < qty) {
                printf("INSUFFICIENT_STOCK sku=%ld\n", sku);
                continue;
            }
            stock[sku] -= qty;
            revenue += price[sku] * qty;
            printf("SELL sku=%ld qty=%ld revenue+=%ld\n", sku, qty, price[sku] * qty);
        } else {
            puts("INVALID_OP");
        }
    }
    // Final report
    printf("FINAL stock=");
    for (int s = 0; s < 5; ++s) {
        if (s > 0) putchar(',');
        printf("%ld", stock[s]);
    }
    printf(" revenue=%ld\n", revenue);
    return 0;
}
